<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';admin_required();$id=max(0,scalar_int($_GET['id']??$_POST['id']??0));
if(is_post()){
    verify_csrf();$action=scalar_string($_POST['action']??'update');
    try{
        if($id<1)throw new RuntimeException('درخواست معتبر نیست.');
        if($action==='update'){
            $status=scalar_string($_POST['status']??'requested');$note=trim(scalar_string($_POST['admin_note']??''));$method=scalar_string($_POST['refund_method']??'');$items=is_array($_POST['items']??null)?$_POST['items']:[];
            admin_update_return($id,$status,$note,$items,$method!==''?$method:null,isset($_POST['send_sms']));flash('success','وضعیت مرجوعی ذخیره شد.');
        }elseif($action==='refund'){
            $amount=max(0,scalar_int($_POST['amount']??0));$method=scalar_string($_POST['method']??'');$reference=trim(scalar_string($_POST['reference']??''));$note=trim(scalar_string($_POST['refund_note']??''));
            complete_return_refund($id,$amount,$method,$reference,$note,isset($_POST['send_sms']));flash('success','بازپرداخت و سند حسابداری ثبت شد.');
        }
    }catch(Throwable $e){log_error($e);flash('error',$e->getMessage());}
    redirect(app_url('admin/return.php?id='.$id));
}
$return=return_request_by_id($id);if(!$return){http_response_code(404);exit('درخواست پیدا نشد.');}$items=return_items_for_request($id);$refundStmt=db()->prepare('SELECT rf.*,a.full_name admin_name FROM refund_transactions rf LEFT JOIN admins a ON a.id=rf.processed_by WHERE rf.return_id=? ORDER BY rf.id DESC');$refundStmt->execute([$id]);$refunds=$refundStmt->fetchAll();$refunded=0;foreach($refunds as $r)if($r['status']==='completed')$refunded+=(int)$r['amount'];$remaining=max(0,(int)$return['approved_amount']-$refunded);$itemsEditable=in_array((string)$return['status'],['requested','reviewing','approved'],true);$adminPage='returns';$adminTitle=$return['return_number'];require __DIR__.'/partials/header.php';?>
<div class="admin-title"><div><h1><?=e($return['return_number'])?></h1><p class="muted"><?=e(return_status_label($return['status']))?> · سفارش <?=e($return['order_number'])?></p></div><div class="admin-actions"><a class="btn btn-secondary" href="<?=e(app_url('admin/returns.php'))?>">بازگشت</a><a class="btn btn-secondary" href="<?=e(app_url('admin/order.php?id='.(int)$return['order_id']))?>">سفارش</a></div></div>
<div class="order-meta"><div><strong>مشتری</strong><br><?=e($return['customer_name'])?><br><?=e($return['phone'])?></div><div><strong>دلیل</strong><br><?=e(return_reason_options()[$return['reason']]??$return['reason'])?></div><div><strong>درخواستی</strong><br><?=fa_number(format_price($return['requested_amount']))?> تومان</div><div><strong>تأیید / پرداخت‌شده</strong><br><?=fa_number(format_price($return['approved_amount']))?> / <?=fa_number(format_price($refunded))?> تومان</div></div>
<?php if($return['customer_note']):?><div class="card" style="margin-top:20px"><h2>توضیحات مشتری</h2><p><?=nl2br(e($return['customer_note']))?></p></div><?php endif?>
<form method="post" class="card" style="margin-top:20px"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="update"><h2>بررسی اقلام</h2><?php if(!$itemsEditable):?><div class="notice-box">پس از دریافت کالا، اطلاعات اقلام و مبالغ قفل می‌شوند تا سوابق انبار و حسابداری تغییر نکنند.</div><?php endif?><div class="table-wrap"><table><thead><tr><th>کالا</th><th>تعداد</th><th>حداکثر مبلغ</th><th>وضعیت کالا</th><th>اقدام موجودی</th><th>مبلغ تأیید</th></tr></thead><tbody><?php foreach($items as $item):$max=(int)$item['unit_price']*(int)$item['quantity'];$optionLabel=order_item_option_label($item);?><tr><td><strong><?=e($item['title'])?></strong><?php if($optionLabel!==''):?><br><small><?=e($optionLabel)?></small><?php endif?><br><small dir="ltr"><?=e($item['sku'])?></small></td><td><?=fa_number($item['quantity'])?></td><td><?=fa_number(format_price($max))?></td><td><select name="items[<?=$item['id']?>][condition_status]" <?=$itemsEditable?'':'disabled'?>><?php foreach(return_condition_options() as $key=>$label):?><option value="<?=$key?>" <?=$item['condition_status']===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select></td><td><select name="items[<?=$item['id']?>][restock_action]" <?=$itemsEditable?'':'disabled'?>><?php foreach(return_restock_options() as $key=>$label):?><option value="<?=$key?>" <?=$item['restock_action']===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select><?php if($item['inventory_processed_at']):?><small class="badge green">پردازش‌شده</small><?php endif?></td><td><input type="number" name="items[<?=$item['id']?>][approved_amount]" min="0" max="<?=$max?>" value="<?=e($item['approved_amount'])?>" style="min-width:150px" <?=$itemsEditable?'':'readonly'?>></td></tr><?php endforeach?></tbody></table></div><div class="form-grid" style="margin-top:18px"><div class="field"><label>وضعیت پرونده</label><select name="status"><?php foreach(return_status_options() as $key=>$label):if($key!==$return['status']&&!return_transition_allowed((string)$return['status'],$key))continue;?><option value="<?=$key?>" <?=$return['status']===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select><small>فقط مرحله‌های مجاز نمایش داده می‌شوند.</small></div><div class="field"><label>روش بازپرداخت</label><select name="refund_method"><option value="">بعداً تعیین می‌شود</option><?php foreach(refund_method_options() as $key=>$label):?><option value="<?=$key?>" <?=$return['refund_method']===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select></div><div class="field full"><label>یادداشت مدیر</label><textarea name="admin_note" maxlength="2000" rows="4"><?=e($return['admin_note']??'')?></textarea></div><div class="field full"><label><input type="checkbox" name="send_sms" value="1" checked> ارسال پیامک وضعیت به مشتری</label></div></div><button class="btn btn-primary">ذخیره بررسی</button></form>
<?php if(in_array($return['status'],['received','refund_pending'],true)&&$remaining>0):?><form method="post" class="card" style="margin-top:20px"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><input type="hidden" name="action" value="refund"><h2>ثبت بازپرداخت انجام‌شده</h2><div class="notice-box">فروشگاه به API استرداد خودکار زیبال متکی نیست. اگر روش زیبال را انتخاب می‌کنید، ابتدا وجه را در پنل زیبال مسترد کنید و سپس شماره مرجع واقعی را اینجا ثبت کنید.</div><div class="form-grid" style="margin-top:16px"><div class="field"><label>مبلغ، تومان</label><input type="number" name="amount" min="1" max="<?=$remaining?>" value="<?=$remaining?>" required></div><div class="field"><label>روش</label><select name="method" required><?php foreach(refund_method_options() as $key=>$label):?><option value="<?=$key?>" <?=($return['refund_method']?:'gateway')===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select></div><div class="field"><label>شماره مرجع / پیگیری</label><input name="reference" maxlength="150" dir="ltr"></div><div class="field full"><label>توضیح بازپرداخت</label><textarea name="refund_note" maxlength="500" rows="3"></textarea></div><div class="field full"><label><input type="checkbox" name="send_sms" value="1" checked> ارسال پیامک بازپرداخت</label></div></div><button class="btn btn-primary">ثبت بازپرداخت</button></form><?php endif?>
<?php if($refunds):?><div class="card" style="margin-top:20px"><h2>سوابق بازپرداخت</h2><div class="table-wrap"><table><thead><tr><th>مبلغ</th><th>روش</th><th>مرجع</th><th>مدیر</th><th>تاریخ</th></tr></thead><tbody><?php foreach($refunds as $r):?><tr><td><?=fa_number(format_price($r['amount']))?></td><td><?=e(refund_method_options()[$r['method']]??$r['method'])?></td><td dir="ltr"><?=e($r['reference_id']?:'—')?></td><td><?=e($r['admin_name']?:'—')?></td><td><?=e(jalali_format($r['processed_at']?:$r['created_at']))?></td></tr><?php endforeach?></tbody></table></div></div><?php endif?>
<?php require __DIR__.'/partials/footer.php';
